window.A4_DASHBOARD_UNITS = [{"unit":1,"theme":"access – make a commitment to","cards":[{"w":"access","p":"v.","d":"to get into or use something","c":"存取","s":"Can you access the database remotely?","t":"您可以遠程存取資料庫嗎？"},{"w":"access","p":"n.","d":"the right or way to enter or use something","c":"存取權","s":"Without proper credentials, one might be denied access to the files.","t":"如果沒有適當的證件，可能會被拒絕存取文件。"},{"w":"adequate","p":"adj.","d":"enough for a need","c":"足夠的","s":"The facilities provided were not adequate for our needs.","t":"所提供的設施不足以滿足我們的需求。"},{"w":"adequately","p":"adv.","d":"in a way that is enough","c":"足夠地","s":"The room wasn't adequately heated during the winter months.","t":"在冬季，房間沒有被足夠地加熱。"},{"w":"annual","p":"adj.","d":"happening once every year","c":"每年的","s":"They hold an annual conference to discuss industry trends.","t":"他們每年舉行一次會議討論行業趨勢。"},{"w":"annually","p":"adv.","d":"once every year","c":"每年","s":"The company's revenue increases annually by about 5%.","t":"公司的收入每年增加約5%。"},{"w":"apparent","p":"adj.","d":"easy to see or understand","c":"明顯的","s":"It's apparent that he's not interested in the proposal.","t":"很明顯，他對提議不感興趣。"},{"w":"apparently","p":"adv.","d":"it seems that; from what people say","c":"顯然地","s":"apparently , she had known about the surprise party all along.","t":"顯然，她一直都知道那個驚喜派對。"},{"w":"approximate","p":"adj.","d":"almost exact but not completely","c":"大約的，近似的","s":"The approximate cost of the project is around $50,000.","t":"該項目的大約成本為50,000美元。"},{"w":"approximately","p":"adv.","d":"about; close to an exact number","c":"大約","s":"There were approximately 200 guests at the event.","t":"活動上大約有200位賓客。"},{"w":"attitude toward(s)","p":"phr.","d":"the way you think and feel about something","c":"對...的態度","s":"His attitude toward success is very humble.","t":"他對成功的態度非常謙虛。"},{"w":"attribute","p":"n.","d":"a quality or feature of something","c":"屬性","s":"Color is one of the main attributes used in design.","t":"顏色是設計中使用的主要屬性之一。"},{"w":"attribute to","p":"v.","d":"to say that something is caused by something","c":"歸因於","s":"The team's victory was attribute tod to their rigorous training.","t":"團隊的勝利歸因於他們的嚴格培訓。"},{"w":"attributed","p":"adj.","d":"said to be caused by or made by someone","c":"歸因於的","s":"The success was attributed to her hard work and dedication.","t":"成功是歸因於她的努力和奉獻。"},{"w":"civil","p":"adj.","d":"about ordinary people, not the army or church","c":"民事的","s":"They were involved in a civil dispute over property rights.","t":"他們涉及民事爭議，關於財產權。"},{"w":"civilian","p":"n.","d":"a person who is not in the army or police","c":"平民","s":"The military base is off-limits to civilians.","t":"軍事基地對平民是禁止進入的。"},{"w":"code","p":"n.","d":"a set of rules or a system of signs","c":"代碼","s":"Each product has a unique barcode code for identification.","t":"每個產品都有一個唯一的條碼代碼用於識別。"},{"w":"commit to","p":"v.","d":"to promise to do something","c":"承諾","s":"She decided to commit to a healthier lifestyle.","t":"她決定承諾一種更健康的生活方式。"},{"w":"make a commitment to","p":"phr.","d":"to promise to do something","c":"作出承諾","s":"They decided to make a commitment to improving the company's sustainability practices.","t":"他們決定承諾改善公司的可持續性做法。"}]},{"unit":2,"theme":"be committed to – dimension","cards":[{"w":"be committed to","p":"phr.","d":"to work very hard for something you believe in","c":"致力於","s":"She is committed to achieving excellence in her field.","t":"她致力於在她的領域中達到卓越。"},{"w":"communicate with","p":"v.","d":"to share information with someone","c":"與...溝通","s":"It's essential to communicate with your team members regularly.","t":"定期與團隊成員溝通非常重要。"},{"w":"communication with","p":"n.","d":"sharing information with someone","c":"與...的溝通","s":"Effective communication with others is a key skill in the workplace.","t":"與他人有效的溝通是工作場所的一項關鍵技能。"},{"w":"concentrate on","p":"v.","d":"to give all your attention to something","c":"專注於","s":"She decided to concentrate on her studies and avoid distractions.","t":"她決定專注於她的學習並避免分心。"},{"w":"concentration","p":"n.","d":"the ability to give all your attention","c":"專注","s":"His concentration on the task was so intense that he didn't notice the time passing.","t":"他對任務的專注程度非常高，以至於他沒有注意到時間過去了。"},{"w":"remain concentrated","p":"phr.","d":"to keep giving all your attention","c":"保持專注","s":"It's crucial to remain concentrated throughout the exam period.","t":"考試期間保持專注是很重要的。"},{"w":"conference","p":"n.","d":"a large formal meeting","c":"會議","s":"They will be attending an international conference in Paris next month.","t":"他們將於下個月參加在巴黎的國際會議。"},{"w":"contrast","p":"n.","d":"a clear difference between two things","c":"對比","s":"The contrast between the two paintings is quite evident.","t":"這兩幅畫之間的對比是非常明顯的。"},{"w":"contrast","p":"v.","d":"to compare two things to show differences","c":"對比","s":"When you contrast the two models, the differences become clear.","t":"當你對比這兩種模型時，差異變得清晰。"},{"w":"in contrast","p":"phr.","d":"showing a difference with something just said","c":"相對於","s":"in contrast, the southern region has a much warmer climate.","t":"相對於，南方地區的氣候要暖和得多。"},{"w":"cycle","p":"v.","d":"to move around in a repeated pattern","c":"循環","s":"Water will naturally cycle between the earth and the atmosphere.","t":"水會在地球和大氣之間自然循環。"},{"w":"cycle","p":"n.","d":"a set of events that repeat in the same order","c":"週期","s":"The life cycle of a butterfly is truly fascinating.","t":"蝴蝶的生命週期真的很吸引人。"},{"w":"cycling","p":"n.","d":"riding a bicycle","c":"騎腳踏車","s":"cycling is both an excellent form of exercise and an environmentally friendly mode of transport.","t":"騎腳踏車既是一種出色的運動形式，又是一種環保的交通方式。"},{"w":"debate","p":"n.","d":"a formal discussion with different opinions","c":"辯論","s":"The political debate was televised nationally.","t":"這場政治辯論在全國範圍內播出。"},{"w":"debate over","p":"v.","d":"to discuss something with different opinions","c":"對...進行辯論","s":"Scientists continue to debate over the effects of climate change on marine life.","t":"科學家們繼續就氣候變化對海洋生物的影響進行辯論。"},{"w":"despite","p":"conj.","d":"even though something happens","c":"儘管","s":"despite the rain, the event went ahead as planned.","t":"儘管下雨，活動仍按計劃進行。"},{"w":"in spite of","p":"phr.","d":"even though something happens","c":"儘管","s":"She managed to smile, in spite of her pain.","t":"她儘管疼痛，還是努力微笑。"},{"w":"regardless of","p":"phr.","d":"without being affected by something","c":"無論","s":"You should treat everyone equally, regardless of their background.","t":"你應該平等地對待每個人，無論他們的背景如何。"},{"w":"dimension","p":"n.","d":"a measurement such as length, width or height","c":"維度","s":"The artwork has a unique three-dimensional dimension.","t":"這件藝術品有獨特的三維維度。"}]},{"unit":3,"theme":"dimensional – implement","cards":[{"w":"dimensional","p":"adj.","d":"having a certain number of dimensions","c":"有...維度的","s":"The artist's work is known for its dimensional quality.","t":"藝術家的作品因其多維度的特質而聞名。"},{"w":"domestic","p":"adj.","d":"about your own country","c":"本國的","s":"The product has been popular both in domestic and international markets.","t":"該產品在國內外市場都很受歡迎。"},{"w":"domestic","p":"adj.","d":"about the home or family","c":"家庭的","s":"Domestic chores can be quite time-consuming.","t":"家庭雜務可能相當耗時。"},{"w":"emerge","p":"v.","d":"to appear or come out","c":"出現","s":"New issues will emerge as the project progresses.","t":"隨著項目的進展，將會出現新的問題。"},{"w":"emerge from","p":"phr.","d":"to come out of something","c":"從...中出現","s":"The butterfly will emerge from its cocoon when it's ready.","t":"當蝴蝶準備好時，它將從它的繭中出現。"},{"w":"emergent","p":"adj.","d":"new and starting to develop","c":"新興的","s":"In recent years, we've seen an emergent trend towards sustainability in the fashion industry.","t":"近年來，我們在時尚行業看到了一個朝向可持續性的新興趨勢。"},{"w":"emergence","p":"n.","d":"the act of appearing","c":"出現","s":"The emergence of digital currencies has transformed the financial landscape.","t":"數位貨幣的出現改變了金融格局。"},{"w":"emergency","p":"n.","d":"a dangerous situation that needs fast action","c":"緊急狀況","s":"In case of an emergency, please call this number.","t":"如果有緊急狀況，請撥打這個號碼。"},{"w":"error","p":"n.","d":"a mistake","c":"錯誤","s":"There was an error in the system that caused the application to crash.","t":"系統中有一個錯誤導致應用程式崩潰。"},{"w":"ethnic","p":"adj.","d":"about a group of people with the same culture","c":"種族的","s":"The festival celebrates the ethnic diversity of the community.","t":"該節日慶祝社區的種族多樣性。"},{"w":"ethic","p":"n.","d":"moral rules about right and wrong","c":"倫理","s":"The doctor adheres to a strict ethic when treating patients.","t":"醫生在治療病人時堅守嚴格的倫理。"},{"w":"goal","p":"n.","d":"something you hope to do","c":"目標","s":"Achieving this goal requires dedication and hard work.","t":"達到這個目標需要奉獻和努力。"},{"w":"grant","p":"n.","d":"money given for a special purpose","c":"補助金","s":"She received a research grant from the government.","t":"她從政府那裡得到了一筆研究補助金。"},{"w":"granted","p":"v.","d":"gave or allowed something officially","c":"批准","s":"The city council granted permission for the new building's construction.","t":"市議會批准了新大樓的建設許可。"},{"w":"take...for granted","p":"phr.","d":"to expect something always and not value it","c":"視為理所當然","s":"We often take for granted the clean air we breathe, not realizing its importance until it's gone.","t":"我們經常把呼吸的乾淨空氣視為理所當然，直到它消失我們才意識到它的重要性。"},{"w":"hence","p":"adv.","d":"for this reason; so","c":"因此","s":"The roads were slippery; hence, driving was dangerous.","t":"道路很滑；因此，開車很危險。"},{"w":"hypothesis","p":"n.","d":"an idea that has not yet been proven","c":"假設","s":"Based on the data, the scientist formulated a new hypothesis.","t":"基於數據，科學家提出了一個新的假設。"},{"w":"hypothesize","p":"v.","d":"to suggest an idea that needs testing","c":"提出假設","s":"Researchers hypothesize that the decline is due to environmental factors.","t":"研究者假設該衰退是由於環境因素造成的。"},{"w":"implement","p":"v.","d":"to put a plan into action","c":"實施","s":"The government decided to implement a new policy to reduce pollution.","t":"政府決定實施一項新政策以減少污染。"}]},{"unit":4,"theme":"implementation – obviously","cards":[{"w":"implementation","p":"n.","d":"putting a plan into action","c":"實施","s":"Proper implementation of the strategy is crucial to its success.","t":"正確實施該策略對其成功至關重要。"},{"w":"imply","p":"v.","d":"to suggest something without saying it directly","c":"暗示","s":"His silence seemed to imply agreement.","t":"他的沉默似乎暗示了同意。"},{"w":"implied","p":"adj.","d":"suggested but not said directly","c":"含蓄的","s":"The implied meaning of his statement was clear to everyone in the room.","t":"他的陳述中的含蓄意義對房間裡的每個人都很清楚。"},{"w":"implication","p":"n.","d":"a possible effect or result","c":"含意","s":"The implication of his words is that he's not satisfied with the results.","t":"他的話意味著他對結果不滿意。"},{"w":"impose ...to","p":"v.","d":"to force a rule or burden on someone","c":"強加於","s":"The government decided to impose new taxes to the citizens.","t":"政府決定向市民徵收新稅。"},{"w":"imposed","p":"adj.","d":"forced on someone","c":"被強加的","s":"The imposed regulations were not popular among the business community.","t":"被強加的規定在商業界並不受歡迎。"},{"w":"integrate","p":"v.","d":"to combine things to work together","c":"整合","s":"Companies often strive to integrate technology into their daily operations.","t":"公司通常努力將技術整合到其日常運營中。"},{"w":"integrated","p":"adj.","d":"combined into one system","c":"整合的","s":"The system is integrated with other software for better efficiency.","t":"該系統與其他軟件整合，以提高效率。"},{"w":"integration","p":"n.","d":"the act of combining things together","c":"整合","s":"The integration of different departments led to smoother operations.","t":"不同部門的整合導致了更順暢的運營。"},{"w":"internal","p":"adj.","d":"inside a place, body or group","c":"內部的","s":"The company had to deal with an internal issue that affected staff morale.","t":"該公司不得不處理影響員工士氣的內部問題。"},{"w":"internalize","p":"v.","d":"to make an idea part of your beliefs","c":"內化","s":"It's important to internalize the values taught to us from a young age.","t":"內化從小就教給我們的價值觀是很重要的。"},{"w":"investigate","p":"v.","d":"to try to find out the facts about something","c":"調查","s":"The detective decided to investigate the mysterious circumstances surrounding the incident.","t":"侦探决定調查事件周圍的神秘情況。"},{"w":"investigation","p":"n.","d":"an official search for the facts","c":"調查","s":"The results of the investigation will be published next month.","t":"調查結果將於下個月公布。"},{"w":"job","p":"n.","d":"work that you do to earn money","c":"工作","s":"Finding a job in this economy can be quite challenging.","t":"在這種經濟環境下找工作可能相當具挑戰性。"},{"w":"label","p":"n.","d":"a piece of paper on something that gives information","c":"標籤","s":"Always read the label before using a new product.","t":"使用新產品前，請務必閱讀標籤。"},{"w":"label","p":"v.","d":"to put a label on something","c":"貼標籤","s":"They decided to label the items based on their importance.","t":"他們決定根據物品的重要性給它們貼標籤。"},{"w":"mechanism","p":"n.","d":"a part of a machine or system that does a job","c":"機制","s":"The mechanism behind the process is intricate and precise.","t":"這個過程背後的機制既複雜又精確。"},{"w":"obvious","p":"adj.","d":"easy to see or understand","c":"明顯的","s":"It's obvious that he's not telling the truth based on his body language.","t":"從他的肢體語言來看，他明顯沒有說實話。"},{"w":"obviously","p":"adv.","d":"clearly; as anyone can see","c":"明顯地","s":"obviously , the team has put in a lot of effort to achieve this result.","t":"顯然，團隊付出了很多努力才達到這個結果。"}]},{"unit":5,"theme":"occupy – predicted","cards":[{"w":"occupy","p":"v.","d":"to take control of a place","c":"佔領","s":"Protesters occupy the city square for three days.","t":"抗議者佔領了市中心廣場三天。"},{"w":"occupy","p":"v.","d":"to fill or use a space or time","c":"占用","s":"His collection occupy two rooms in his house.","t":"他的收藏占用了他家的兩間房間。"},{"w":"be occupied with","p":"phr.","d":"to be busy doing something","c":"忙於","s":"She's currently occupied with preparations for the upcoming event.","t":"她目前忙於為即將到來的活動做準備。"},{"w":"occupied","p":"adj.","d":"being used; taken over by someone","c":"被佔領的","s":"The meeting room is already occupied by another team.","t":"會議室已被另一支團隊佔用。"},{"w":"occupation","p":"n.","d":"taking control of a place by force","c":"佔領","s":"The occupation of the building ended after a week.","t":"該建築物的佔領在一週後結束。"},{"w":"occupation","p":"n.","d":"a job","c":"職業","s":"His occupation is a software engineer, and he's been in the field for over 10 years.","t":"他的職業是軟件工程師，並且已經從事這個行業超過10年了。"},{"w":"occupational","p":"adj.","d":"about a person's job","c":"職業的","s":"occupational hazards are risks that people face in their line of work.","t":"職業風險是人們在工作中面臨的風險。"},{"w":"opt to","p":"phr.","d":"to choose to do something","c":"選擇","s":"She decided to opt to take the longer but more scenic route.","t":"她決定選擇更長但更風景優美的路線。"},{"w":"opt for","p":"phr.","d":"to choose something","c":"選擇","s":"Given the options, many customers opt for organic products.","t":"鑑於選擇，許多顧客選擇有機產品。"},{"w":"option","p":"n.","d":"a choice","c":"選項","s":"There are multiple option available, but we need to choose the most viable one.","t":"有多個選項可供選擇，但我們需要選擇最可行的一個。"},{"w":"optional","p":"adj.","d":"not required; you can choose","c":"可選的","s":"Attendance at the workshop is optional , but I recommend going as it's very informative.","t":"參加研討會是可選的，但我建議去，因為它資訊豐富。"},{"w":"output","p":"n.","d":"the amount that is produced","c":"產量","s":"The factory's monthly output has doubled since they introduced the new machinery.","t":"自從他們引入新的機器以來，工廠的月產量已經翻倍。"},{"w":"overall","p":"adv.","d":"in general; as a whole","c":"總體上","s":"overall , the event was a success even though there were minor issues.","t":"總體上，即使有些小問題，該活動還是成功的。"},{"w":"parallel","p":"n.","d":"a line that never meets another line","c":"平行線","s":"Geometry studies shapes, lines, and parallel , among other things.","t":"幾何學研究形狀、線條和平行線等等。"},{"w":"parallel","p":"adj.","d":"always the same distance apart","c":"平行的","s":"The two streets are parallel and never intersect.","t":"這兩條街道是平行的，永遠不會相交。"},{"w":"parameter","p":"n.","d":"a limit that controls how something is done","c":"參數","s":"Adjusting the parameter of the experiment might yield different results.","t":"調整實驗的參數可能會產生不同的結果。"},{"w":"phase","p":"n.","d":"one stage of a process","c":"階段","s":"The project is now entering its final phase .","t":"該項目現在正在進入其最後階段。"},{"w":"predict","p":"v.","d":"to say what will happen in the future","c":"預測","s":"Based on the data, we can predict a positive trend in the upcoming months.","t":"根據這些數據，我們可以預測接下來幾個月會有一個正向的趨勢。"},{"w":"predicted","p":"adj.","d":"expected to happen","c":"被預測的","s":"The predicted storm caused the event to be postponed.","t":"被預測的暴風雨導致活動被延後。"}]},{"unit":6,"theme":"unpredicted – resolution","cards":[{"w":"unpredicted","p":"adj.","d":"not expected","c":"未預測到的","s":"The sudden rainfall was unpredicted and caught many off guard.","t":"突然的雨水是未預測到的，讓許多人措手不及。"},{"w":"make prediction","p":"phr.","d":"to say what will happen in the future","c":"作預測","s":"Meteorologists use various tools to make prediction about the weather.","t":"氣象學家使用各種工具來預測天氣。"},{"w":"principal","p":"n.","d":"the head of a school","c":"校長；主要","s":"The school's principal will give a speech at the graduation ceremony.","t":"學校的校長將在畢業典禮上發表演講。"},{"w":"principle","p":"n.","d":"a basic rule or belief","c":"原則","s":"It's important to stand by your principle , even when faced with challenges.","t":"面對挑戰時，堅持你的原則很重要。"},{"w":"prior to","p":"phr.","d":"before","c":"在...之前","s":"prior to the meeting, please ensure all reports are submitted.","t":"在會議之前，請確保所有報告都已提交。"},{"w":"prior","p":"adj.","d":"earlier; happening before","c":"先前的","s":"She had prior experience in marketing before joining our team.","t":"她在加入我們團隊之前已有市場營銷經驗。"},{"w":"profession","p":"n.","d":"a job that needs special training","c":"職業","s":"Nursing is a noble profession that requires dedication and compassion.","t":"護理是一個需要奉獻和同情心的高尚職業。"},{"w":"professional","p":"adj.","d":"having special skills; about a job","c":"專業的","s":"Her professional attitude impressed everyone at the conference.","t":"她在會議上的專業態度給大家留下了深刻的印象。"},{"w":"project","p":"n.","d":"a planned piece of work","c":"專案","s":"The entire team worked on the project for months to ensure its success.","t":"整個團隊花了數月的時間來確保該專案的成功。"},{"w":"project","p":"v.","d":"to show an image on a screen; to plan or expect","c":"投影，預計","s":"Analysts project that the economy will recover by next year.","t":"分析師預計明年經濟將會復蘇。"},{"w":"projector","p":"n.","d":"a machine that shows images on a screen","c":"投影機","s":"We need a projector for the presentation in the conference room.","t":"我們需要一台投影機進行會議室的演示。"},{"w":"promote","p":"v.","d":"to help something grow; to give a higher job","c":"促進，提升","s":"Companies often promote their products through advertising campaigns.","t":"公司經常通過廣告活動來推廣他們的產品。"},{"w":"promotion","p":"n.","d":"a higher job; a special offer to sell more","c":"升遷，促銷活動","s":"After years of hard work, she finally received a promotion at her job.","t":"在多年的努力工作之後，她終於在工作中得到了晉升。"},{"w":"promotional","p":"adj.","d":"used to advertise something","c":"促銷的","s":"The store is offering promotional discounts to attract more customers.","t":"該商店正在提供促銷折扣以吸引更多的顧客。"},{"w":"regime","p":"n.","d":"a government or system of rule","c":"政權，制度","s":"The new regime promised economic reforms to boost growth.","t":"新政權承諾進行經濟改革以促進增長。"},{"w":"resolve","p":"v.","d":"to find an answer to a problem","c":"解決","s":"The committee met to resolve the issues raised during the last session.","t":"委員會召開會議以解決上次會議中提出的問題。"},{"w":"resolve","p":"n.","d":"a strong decision to do something","c":"決心","s":"With firm resolve and determination, she overcame all challenges in her way.","t":"憑著堅定的決心和毅力，她克服了她面前的所有挑戰。"},{"w":"be resolved to","p":"phr.","d":"to be determined to do something","c":"決心要","s":"She was resolved to complete her studies despite the financial hardships.","t":"儘管經濟上有困難，她仍決心完成學業。"},{"w":"resolution","p":"n.","d":"a formal decision; a promise to yourself","c":"決議，決定","s":"The board passed a resolution to increase funding for the project.","t":"董事會通過了一項決議，增加專案的資金。"}]},{"unit":7,"theme":"retain – undertaking","cards":[{"w":"retain","p":"v.","d":"to keep something","c":"保留","s":"The company decided to retain its older employees due to their vast experience.","t":"由於他們的豐富經驗，公司決定保留其資深員工。"},{"w":"retained","p":"adj.","d":"kept","c":"被保留的","s":"The retained knowledge from the workshop greatly benefited the team.","t":"從工作坊中獲得的知識對團隊大有裨益。"},{"w":"series","p":"n.","d":"a number of related things in order","c":"系列","s":"The author released the third book in the popular series.","t":"作者發布了受歡迎的系列的第三本書。"},{"w":"a series of","p":"phr.","d":"several related things one after another","c":"一系列","s":"The museum is hosting a series of events throughout the summer.","t":"博物館將在整個夏季舉辦一系列活動。"},{"w":"statistics","p":"n.","d":"numbers that give information about something","c":"統計數據","s":"According to recent statistics , the unemployment rate has dropped significantly.","t":"根據最近的統計數據，失業率已大幅下降。"},{"w":"status","p":"n.","d":"position or rank in a group","c":"狀態，地位","s":"The status of the order is still 'processing'.","t":"訂單的狀態仍然是'正在處理中'。"},{"w":"stress","p":"v.","d":"to show that something is important","c":"強調","s":"The teacher stress the importance of regular study habits.","t":"老師強調定期學習習慣的重要性。"},{"w":"stress","p":"n.","d":"a feeling of worry because of problems","c":"壓力","s":"High levels of stress can lead to various health issues.","t":"高壓力水平可能導致各種健康問題。"},{"w":"be stressed out","p":"phr.","d":"very worried and nervous","c":"非常緊張","s":"Due to the looming deadlines, many employees were stressed out.","t":"由於即將到來的截止日期，許多員工都感到非常緊張。"},{"w":"stressful","p":"adj.","d":"causing worry","c":"有壓力的","s":"Preparing for an international conference can be very stressful.","t":"為國際會議做準備可能非常有壓力。"},{"w":"be under stress","p":"phr.","d":"feeling a lot of pressure","c":"處於壓力之下","s":"Due to multiple projects at hand, he is currently under stress.","t":"由於手頭有多個專案，他目前處於壓力之下。"},{"w":"subsequent","p":"adj.","d":"coming after something else","c":"隨後的","s":"The main event will start at 6 pm, with a subsequent dinner at 8 pm.","t":"主要活動將於下午6點開始，隨後的晚餐將於8點舉行。"},{"w":"sum","p":"v.","d":"to give a short summary","c":"總結","s":"Please sum up the main points of the meeting for those who were absent.","t":"請為缺席的人總結會議的主要要點。"},{"w":"sum","p":"n.","d":"the total when numbers are added","c":"總和","s":"The sum of 5 and 3 is 8.","t":"5加3的總和是8。"},{"w":"summary","p":"n.","d":"a short statement of the main points","c":"概要，摘要","s":"Can you give me a brief summary of the article?","t":"你能給我一個文章的簡短摘要嗎？"},{"w":"summarize","p":"v.","d":"to give the main points briefly","c":"總結","s":"He was able to summarize the lengthy report in just a few sentences.","t":"他能夠用幾句話總結那份冗長的報告。"},{"w":"undertake-undertook-undertaken","p":"v.","d":"to agree to do a job or task","c":"承擔","s":"The company decided to undertake-undertook-undertaken a new initiative to reduce waste.","t":"公司決定承擔一項減少浪費的新計劃。"},{"w":"undertaken","p":"adj.","d":"already started or done as a job","c":"已承擔的","s":"All undertaken projects should be completed by the end of the month.","t":"所有已承擔的項目應在月底前完成。"},{"w":"undertaking","p":"n.","d":"a big job or task you agree to do","c":"承諾，任務","s":"Organizing the annual event is no small undertaking.","t":"組織年度活動絕非小任務。"}]}];
